  const early=await indicatorRects();await frame.evaluate(()=>document.fonts.ready.then(()=>document.fonts.status));await delay(150);const fontReady=await indicatorRects();await page.setViewportSize({width:1400,height:650});await word.hover();await page.mouse.wheel(0,120);await delay(150);const afterScroll=await indicatorRects();await page.mouse.wheel(0,-120);await delay(150);const returned=await indicatorRects();await page.setViewportSize({width:1400,height:1000});await fs.writeFile(path.join(output,'indicator-live-geometry.json'),JSON.stringify({early,fontReady,afterScroll,returned},null,2));
