  await mark(['R-3.1'],'PASS','Actual computed1px underline and native screenshot retained; rendered underline unchanged before/after text hover; screenshot and computed paint values retained',[...await observe('word-hover-indicator'),'underline-before-after.json']);await mark(['R-3.3'],'PASS','Two actual dots including original, exactly second active',ev);await mark(['R-3.6'],'PASS','Inactive-dot hover without click plus both arrows leaves text unchanged; text-hover Up/Down positive controls cycle',ev);await mark(['R-2.4'],'PASS','Actual text-hover Up/Down cycles complete active variant in context',await observe('text-hover-cycled'));
